svg.script:
/*  */
(function() {
  var root = document.getElementById('a12p16-svg');
  if (!root) return;

  var scenes = {
    obturador: {
      badge: 'PAREDE LATERAL (NÃO É CHÃO)',
      badgeColor: 'var(--a12p16-parede)',
      title: 'M. Obturador Interno',
      desc1: 'Músculo calibroso que reveste verticalmente a parede óssea lateral da pelve menor.',
      desc2: 'Embora seja vizinho do levantador do ânus, SUA FUNÇÃO É REVESTIMENTO DA PAREDE e rotação do quadril.',
      desc3: 'NÃO compõe o chão pélvico nem o diafragma!',
      desc3Color: 'var(--a12p16-parede)',
      alertHeader: 'DISTRATOR PERIGOSO DE PROVA',
      alertHeaderColor: 'var(--a12p16-pubococcigeo)',
      alert1: '⚠️ O Obturador Interno é o maior',
      alert2: 'distrator em questões de assoalho.',
      alert3: 'Vizinhança anatômica NÃO significa',
      alert4: 'pertencimento ao chão pélvico!',
      alert4Color: 'var(--a12p16-parede)'
    },
    levantador: {
      badge: 'CHÃO PÉLVICO (SUSTENTAÇÃO)',
      badgeColor: 'var(--a12p16-chao)',
      title: 'M. Levantador do Ânus + Coccígeo',
      desc1: 'Conjunto muscular que forma o verdadeiro Diafragma Pélvico (funil inferior de suporte).',
      desc2: 'Ejerce vetor de suporte vertical ascendente contra a pressão intra-abdominal sustentando as vísceras.',
      desc3: 'Este SIM é o verdadeiro chão anatômico!',
      desc3Color: 'var(--a12p16-chao)',
      alertHeader: 'CONCEITO-CHAVE ANATÔMICO',
      alertHeaderColor: 'var(--a12p16-chao)',
      alert1: '✅ O Diafragma Pélvico é composto',
      alert2: 'pelo M. Levantador do Ânus (pubo-',
      alert3: 'coccígeo, iliococcígeo, puborretal)',
      alert4: 'e pelo Músculo Coccígeo.',
      alert4Color: 'var(--a12p16-chao)'
    },
    pubococcigeo: {
      badge: 'ALVO DO TREINO DE KEGEL',
      badgeColor: 'var(--a12p16-pubococcigeo)',
      title: 'Feixe Pubococcígeo',
      desc1: 'Feixe muscular medial e nobre do M. Levantador do Ânus que abraça os hiatos urogenital e anal.',
      desc2: 'É a principal porção contrátil voluntária responsável pela continência e sustentação visceral direta.',
      desc3: 'Alvo principal da fisioterapia pélvica!',
      desc3Color: 'var(--a12p16-pubococcigeo)',
      alertHeader: 'APLICAÇÃO CLÍNICA PRÁTICA',
      alertHeaderColor: 'var(--a12p16-pubococcigeo)',
      alert1: '💡 Fortalecido ativamente durante os',
      alert2: 'Exercícios de Kegel na reabilitação',
      alert3: 'perineal para tratamento de prolapsos',
      alert4: 'e incontinência urinária de esforço.',
      alert4Color: 'var(--a12p16-pubococcigeo)'
    },
    arco: {
      badge: 'JUNÇÃO PAREDE–CHÃO',
      badgeColor: 'var(--a12p16-arco)',
      title: 'Arco Tendíneo (ATLA)',
      desc1: 'Espessamento aponeurótico da fáscia obturatória ao longo da parede lateral da pelve.',
      desc2: 'Serve de linha de origem suspensória para as fibras do M. Levantador do Ânus na parede.',
      desc3: 'Marco de transição: parede acima, chão abaixo.',
      desc3Color: 'var(--a12p16-arco)',
      alertHeader: 'REGRA DE TRANSIÇÃO FASCIAL',
      alertHeaderColor: 'var(--a12p16-arco)',
      alert1: '📌 O Arco Tendíneo NÃO é músculo,',
      alert2: 'é um espessamento fascial que marca',
      alert3: 'onde a parede lateral termina e',
      alert4: 'o chão pélvico se origina.',
      alert4Color: 'var(--a12p16-arco)'
    }
  };

  function updatePanel(sceneKey) {
    var data = scenes[sceneKey];
    if (!data) return;

    root.setAttribute('data-active-scene', sceneKey);

    var badgeBg = document.getElementById('a12p16-panel-badge-bg');
    var badgeTxt = document.getElementById('a12p16-panel-badge-text');
    var title = document.getElementById('a12p16-panel-title');
    var desc1 = document.getElementById('a12p16-panel-desc-1');
    var desc2 = document.getElementById('a12p16-panel-desc-2');
    var desc3 = document.getElementById('a12p16-panel-desc-3');
    var a1 = document.getElementById('a12p16-panel-alert-1');
    var a2 = document.getElementById('a12p16-panel-alert-2');
    var a3 = document.getElementById('a12p16-panel-alert-3');
    var a4 = document.getElementById('a12p16-panel-alert-4');

    if (badgeBg) badgeBg.style.fill = data.badgeColor;
    if (badgeTxt) badgeTxt.textContent = data.badge;
    if (title) title.textContent = data.title;
    if (desc1) desc1.textContent = data.desc1;
    if (desc2) desc2.textContent = data.desc2;
    if (desc3) {
      desc3.textContent = data.desc3;
      desc3.style.fill = data.desc3Color;
    }
    if (a1) a1.textContent = data.alert1;
    if (a2) a2.textContent = data.alert2;
    if (a3) a3.textContent = data.alert3;
    if (a4) {
      a4.textContent = data.alert4;
      a4.style.fill = data.alert4Color;
    }
  }

  function attachEvents() {
    var targets = root.querySelectorAll('.a12p16-interactive-item');
    for (var i = 0; i < targets.length; i++) {
      (function(el) {
        function trigger() {
          var targetScene = el.getAttribute('data-hs-target');
          if (targetScene) {
            updatePanel(targetScene);
          }
        }
        el.addEventListener('click', trigger);
        el.addEventListener('keydown', function(e) {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            trigger();
          }
        });
      })(targets[i]);
    }
  }

  attachEvents();
})();
/*  */
